<?php
require_once __DIR__ . '/../includes/bootstrap.php';
requireCustomer('login.php');
$customer = currentCustomer(); $message = ''; $error = '';
// TODO: ajouter customer_addresses et le choix d'adresse dans le tunnel de commande.
// TODO: ajouter wishlist, favoris client et partage de liste si cette option est activée.
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    $action = isset($_POST['action']) ? $_POST['action'] : '';
    if ($action === 'profile') {
        $name = trim(isset($_POST['full_name']) ? $_POST['full_name'] : ''); $email = strtolower(trim(isset($_POST['email']) ? $_POST['email'] : '')); $phone = trim(isset($_POST['phone']) ? $_POST['phone'] : ''); $city = trim(isset($_POST['city']) ? $_POST['city'] : '');
        if (!preg_match('/^[\p{L}][\p{L} \-\']{1,99}$/u', $name) || !filter_var($email, FILTER_VALIDATE_EMAIL) || !preg_match('/^(?:6\d{8}|\+2376\d{8})$/', $phone) || $city === '') $error = 'Informations personnelles invalides.';
        else { try { db()->prepare('UPDATE customers SET full_name=?,email=?,phone=?,city=? WHERE id=?')->execute([$name,$email,$phone,$city,$customer['id']]); $message = 'Informations mises à jour.'; $stmt = db()->prepare('SELECT * FROM customers WHERE id=?'); $stmt->execute([$customer['id']]); $customer = $stmt->fetch(); } catch (PDOException $exception) { $error = 'Cet email ou ce numéro est déjà utilisé.'; } }
    } elseif ($action === 'password') {
        $old = isset($_POST['old_password']) ? $_POST['old_password'] : ''; $new = isset($_POST['new_password']) ? $_POST['new_password'] : ''; $confirm = isset($_POST['confirm_password']) ? $_POST['confirm_password'] : '';
        if (!password_verify($old, $customer['password']) || !preg_match('/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d).{8,}$/', $new) || $new !== $confirm) $error = 'Mot de passe actuel, nouveau mot de passe ou confirmation invalide.';
        else { db()->prepare('UPDATE customers SET password=? WHERE id=?')->execute([password_hash($new, PASSWORD_DEFAULT),$customer['id']]); $message = 'Mot de passe modifié.'; }
    }
}
$count = db()->prepare('SELECT COUNT(*) FROM orders WHERE customer_id=?'); $count->execute([$customer['id']]); $ordersCount = (int)$count->fetchColumn();
$spentStmt = db()->prepare("SELECT COALESCE(SUM(total_amount),0) FROM orders WHERE customer_id=? AND status <> 'Annulée'"); $spentStmt->execute([$customer['id']]); $spent = (float)$spentStmt->fetchColumn();
$itemStmt = db()->prepare('SELECT COALESCE(SUM(oi.quantity),0) FROM order_items oi JOIN orders o ON o.id=oi.order_id WHERE o.customer_id=?'); $itemStmt->execute([$customer['id']]); $itemCount = (int)$itemStmt->fetchColumn();
$topStmt = db()->prepare("SELECT p.name,SUM(oi.quantity) quantity FROM order_items oi JOIN products p ON p.id=oi.product_id JOIN orders o ON o.id=oi.order_id WHERE o.customer_id=? AND o.status <> 'Annulée' GROUP BY oi.product_id ORDER BY quantity DESC LIMIT 3"); $topStmt->execute([$customer['id']]); $topProducts = $topStmt->fetchAll();
$discounts = db()->query("SELECT * FROM discounts WHERE is_active=1 AND valid_from <= CURDATE() AND valid_until >= CURDATE() AND (usage_limit IS NULL OR usage_count < usage_limit) ORDER BY valid_until")->fetchAll();
$usedStmt = db()->prepare('SELECT d.code,du.used_at,du.order_id FROM discount_usage du JOIN discounts d ON d.id=du.discount_id WHERE du.customer_id=? ORDER BY du.used_at DESC'); $usedStmt->execute([$customer['id']]); $usedDiscounts = $usedStmt->fetchAll();
$firstName = explode(' ', trim($customer['full_name']))[0]; $loyalty = $spent > 100000 ? 'Gold' : ($spent > 50000 ? 'Silver' : 'Bronze');
?><!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Mon compte | Woodin</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.0/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><main class="container py-4"><div class="d-flex justify-content-between"><div><small>Espace membre WOODIN</small><h1>Bonjour <?= e($firstName) ?> !</h1></div><a href="logout.php">Déconnexion</a></div><?php if ($message): ?><div class="alert alert-success"><?= e($message) ?></div><?php endif; ?><?php if ($error): ?><div class="alert alert-danger"><?= e($error) ?></div><?php endif; ?><div class="row g-3 my-3"><?php foreach ([['Membre depuis',date('d/m/Y',strtotime($customer['created_at']))],['Commandes',$ordersCount],['Total dépensé',number_format($spent,0,',',' ').' FCFA'],['Fidélité','Client '.$loyalty],['Articles achetés',$itemCount]] as $stat): ?><div class="col-sm-6 col-lg"><div class="card p-3 h-100"><small><?= e($stat[0]) ?></small><strong><?= e($stat[1]) ?></strong></div></div><?php endforeach; ?></div><div class="row g-3"><div class="col-lg-8"><section class="card p-4"><h2 class="h4">Mes informations</h2><form method="post" class="row g-2"><input type="hidden" name="action" value="profile"><?php foreach ([['full_name','Nom complet','text',$customer['full_name']],['email','Email','email',$customer['email']],['phone','Téléphone','text',$customer['phone']],['city','Ville','text',$customer['city']]] as $field): ?><div class="col-md-6"><label><?= e($field[1]) ?></label><input class="form-control" type="<?= $field[2] ?>" name="<?= e($field[0]) ?>" value="<?= e($field[3]) ?>" required></div><?php endforeach; ?><div class="col-12"><button class="btn btn-warning">Modifier</button></div></form></section><section class="card p-4 mt-3"><h2 class="h4">Changer mon mot de passe</h2><form method="post" class="row g-2"><input type="hidden" name="action" value="password"><div class="col-md-4"><input class="form-control" type="password" name="old_password" placeholder="Ancien mot de passe" required></div><div class="col-md-4"><input class="form-control" type="password" name="new_password" placeholder="Nouveau mot de passe" required></div><div class="col-md-4"><input class="form-control" type="password" name="confirm_password" placeholder="Confirmation" required></div><div class="col-12"><button class="btn btn-dark">Changer</button></div></form></section><section class="card p-4 mt-3"><h2 class="h4">Codes promo actifs</h2><?php foreach ($discounts as $discount): ?><p><strong><?= e($discount['code']) ?></strong> : <?= e($discount['value']) ?> <?= $discount['type'] === 'percentage' ? '%' : 'FCFA' ?> <a href="../panier.php?promo=<?= urlencode($discount['code']) ?>">Utiliser maintenant</a></p><?php endforeach; ?><?php if (!$discounts): ?><p>Aucun code actif.</p><?php endif; ?><h3 class="h6">Codes utilisés</h3><?php foreach ($usedDiscounts as $used): ?><p class="text-muted"><?= e($used['code']) ?> · commande #<?= (int)$used['order_id'] ?></p><?php endforeach; ?></section></div><aside class="col-lg-4"><section class="card p-4"><h2 class="h4">Navigation</h2><a class="d-block mb-2" href="mes-commandes.php">Mes commandes</a><a class="d-block mb-2" href="mes-factures.php">Mes factures</a><a class="d-block mb-2" href="../catalogue.php">Continuer mes achats</a></section><section class="card p-4 mt-3"><h2 class="h4">Top produits</h2><?php foreach ($topProducts as $top): ?><p><?= e($top['name']) ?> (<?= (int)$top['quantity'] ?>)</p><?php endforeach; ?></section><section class="card p-4 mt-3"><h2 class="h4">Support</h2><p>+237 696 80 92 64<br><a href="mailto:contact.cm@belifegroupe.com">contact.cm@belifegroupe.com</a></p><a class="btn btn-success" href="https://wa.me/237696809264" target="_blank" rel="noopener">WhatsApp</a><a class="d-block mt-2" href="../contact.php">FAQ et contact</a></section></aside></div></main></body></html>
